1	{
2	  "$schema": "https://json-schema.org/draft/2020-12/schema",
3	  "title": "Pipeline Analysis Finding",
4	  "description": "Schema for finding.json — a per-group structured finding written by AI during Phase 3 root-cause analysis. Validated by the orchestrator immediately after the analysis agent completes.",
5	  "type": "object",
6	  "required": [
7	    "group_id",
8	    "title",
9	    "collections",
10	    "error_summary",
11	    "suggested_resolution_summary",
12	    "has_resolution_file",
13	    "confidence",
14	    "confidence_justification",
15	    "cascade",
16	    "group_consistency",
17	    "feedback_status",
18	    "references",
19	    "resources_used"
20	  ],
21	  "additionalProperties": false,
22	  "properties": {
23	    "group_id": {
24	      "type": "string",
25	      "description": "Slug identifier for the failure group, used in directory paths (e.g. '01-numpy-constraint-conflict')."
26	    },
27	    "title": {
28	      "type": "string",
29	      "description": "Short descriptive title summarizing the failure group."
30	    },
31	    "collections": {
32	      "type": "array",
33	      "items": {
34	        "type": "string"
35	      },
36	      "description": "Collections affected by this failure group. Can be empty for non-collection-specific groups."
37	    },
38	    "actions": {
39	      "type": "array",
40	      "items": {
41	        "type": "string"
42	      },
43	      "description": "Pipeline actions that failed (e.g. ['build-wheels']). When a group spans multiple (collection, action) pairs, lists all unique actions."
44	    },
45	    "error_summary": {
46	      "type": "string",
47	      "description": "Human-readable one-line summary of the error."
48	    },
49	    "suggested_resolution_summary": {
50	      "type": "string",
51	      "description": "One-line summary of the suggested fix."
52	    },
53	    "has_resolution_file": {
54	      "type": "boolean",
55	      "description": "Whether a sections/resolution.md file exists with detailed resolution steps."
56	    },
57	    "confidence": {
58	      "type": "string",
59	      "enum": ["high", "medium", "low"],
60	      "description": "Confidence level in the root-cause diagnosis."
61	    },
62	    "confidence_justification": {
63	      "type": "string",
64	      "description": "Evidence and reasoning supporting the confidence level."
65	    },
66	    "cascade": {
67	      "type": "boolean",
68	      "description": "Whether this failure cascades from an upstream failure rather than being an independent root cause."
69	    },
70	    "group_consistency": {
71	      "type": "string",
72	      "enum": ["consistent", "mixed"],
73	      "description": "Whether all jobs show the same error symptoms ('consistent') or exhibit different error manifestations despite sharing a root cause ('mixed'). Same root cause with variant-specific symptoms = 'mixed'."
74	    },
75	    "feedback_status": {
76	      "type": "string",
77	      "enum": ["included", "not_applicable"],
78	      "description": "Whether workflow feedback was written. 'included' when feedback.md was written, 'not_applicable' when no process observations apply."
79	    },
80	    "references": {
81	      "type": "array",
82	      "items": {
83	        "type": "object",
84	        "required": ["path"],
85	        "additionalProperties": false,
86	        "properties": {
87	          "path": {
88	            "type": "string",
89	            "description": "Canonical repository path consulted during analysis."
90	          },
91	          "description": {
92	            "type": "string",
93	            "description": "How this reference was used during the investigation and what insight it provided."
94	          }
95	        }
96	      },
97	      "description": "Repository files consulted during analysis, with descriptions of how each was used."
98	    },
99	    "target_repo": {
100	      "type": "string",
101	      "format": "uri",
102	      "description": "Full URL of the GitLab repository where the fix should be applied (e.g. 'https://gitlab.com/redhat/rhel-ai/rhai/pipeline'). Omit when the fix location is unclear or no code fix exists."
103	    },
104	    "target_repo_reason": {
105	      "type": "string",
106	      "description": "1-2 sentence justification for why target_repo was chosen (e.g. which files need changing and why they live in that repo)."
107	    },
108	    "resources_used": {
109	      "type": "object",
110	      "description": "Workspace resources consulted during analysis.",
111	      "required": ["agent_docs", "skills", "tools"],
112	      "additionalProperties": false,
113	      "properties": {
114	        "agent_docs": {
115	          "type": "array",
116	          "items": {
117	            "type": "object",
118	            "required": ["name"],
119	            "additionalProperties": false,
120	            "properties": {
121	              "name": {
122	                "type": "string",
123	                "description": "Agent documentation filename (e.g. 'package-constraints.md')."
124	              },
125	              "description": {
126	                "type": "string",
127	                "description": "How this documentation was used and what insight it provided."
128	              }
129	            }
130	          },
131	          "description": "Agent documentation files consulted during analysis."
132	        },
133	        "skills": {
134	          "type": "array",
135	          "items": {
136	            "type": "object",
137	            "required": ["name"],
138	            "additionalProperties": false,
139	            "properties": {
140	              "name": {
141	                "type": "string",
142	                "description": "Skill name."
143	              },
144	              "description": {
145	                "type": "string",
146	                "description": "How this skill was used and what it accomplished."
147	              }
148	            }
149	          },
150	          "description": "Skills invoked during analysis."
151	        },
152	        "tools": {
153	          "type": "array",
154	          "items": {
155	            "type": "object",
156	            "required": ["name"],
157	            "additionalProperties": false,
158	            "properties": {
159	              "name": {
160	                "type": "string",
161	                "description": "Tool or MCP server name."
162	              },
163	              "description": {
164	                "type": "string",
165	                "description": "How this tool was used beyond baseline operations."
166	              }
167	            }
168	          },
169	          "description": "Tools used during analysis beyond what the prompt explicitly instructed."
170	        }
171	      }
172	    }
173	  }
174	}
